        EQ("401 означає…", "401 means…", ["не автентифіковано", "автентифіковано, але заборонено", "успішне створення", "ліміт вичерпано"], 0, "Немає валідних облікових даних.", "There are no valid credentials."),
        EQ("403 означає…", "403 means…", ["користувач відомий, прав на ресурс немає", "завжди анонім", "ліміт вичерпано", "ресурс назавжди прибрано"], 0, "Заборона після входу.", "A denial after login."),
        EQ("Перевищення квоти відповідають…", "Exceeding a quota is answered with…", ["429 і Retry-After", "401", "201", "101"], 0, "Зачекай і повтори.", "Wait and retry."),
        EQ("OpenAPI у CI потрібен, щоб…", "OpenAPI in CI is needed so that…", ["розходження коду й контракту стало дефектом", "сховати документацію", "замінити автентифікацію", "вимкнути статус-коди"], 0, "Контракт перевіряють.", "The contract is checked."),
        EQ("У прикладах специфікації секрети мають бути…", "In specification examples secrets must be…", ["фіктивними", "бойовими продакшен-токенами", "паролями реальних користувачів", "приватними ключами сервера"], 0, "Не світити бойове.", "Do not leak live secrets."),
